Lemma bases_dominated : forall L cs mb ms n,
  Forall (sec_wf1 L) cs -> sec_disjoint cs -> In (CSec mb ms n) cs ->
  Forall (fun b => 0 <= b < 2^64 /\ (b <= mb + 6128 -> b <= mb)) (map sec_mb cs).
